import{_ as a,a as t,b as o,c as s,d as l,e as i,f as n}from"./chunks/exp_past.Cag4dFyC.js";import{_ as r,o as u,c as p,aa as h}from"./chunks/framework.BAs_AphD.js";const y=JSON.parse('{"title":"Problémy s přihlášením","description":"","frontmatter":{"title":"Problémy s přihlášením","wiki":"cs:firstofall:loginproblems"},"headers":[],"relativePath":"firstofall/loginproblems.md","filePath":"firstofall/loginproblems.md","lastUpdated":1794209661000}'),m={name:"firstofall/loginproblems.md"};function c(d,e,b,f,k,g){return u(),p("div",null,[...e[0]||(e[0]=[h('<h1 id="problemy-s-prihlasenim" tabindex="-1">Problémy s přihlášením <a class="header-anchor" href="#problemy-s-prihlasenim" aria-label="Permalink to &quot;Problémy s přihlášením&quot;">​</a></h1><p>Najděte hlášku, kterou vám aplikace ukázala, a postupujte podle řešení. Další potíže najdete v <a href="/buildary-help-preview/caste-dotazy">častých dotazech</a>.</p><h2 id="neplatny-e-mail-nebo-heslo" tabindex="-1">Neplatný e-mail nebo heslo <a class="header-anchor" href="#neplatny-e-mail-nebo-heslo" aria-label="Permalink to &quot;Neplatný e-mail nebo heslo&quot;">​</a></h2><figure class="shot" style="--w:240px;"><img src="'+a+'" alt="Hláška Neplatný e-mail nebo heslo" loading="lazy"></figure><ul><li><strong>Překlep v e-mailu nebo hesle.</strong> Zkontrolujte, co jste zadali, a zkuste to znovu.</li><li><strong>Přihlašujete se Microsoft účtem.</strong> Pokud jste se někdy přihlásili tlačítkem <strong>Přihlásit se pomocí Microsoft účtu</strong>, e-mail a heslo už nefungují – použijte to tlačítko. Pokud jste to nikdy neudělali, klikněte na <strong>Zapomněl jsem heslo</strong> a řiďte se pokyny v e-mailu.</li></ul><h2 id="ucet-byl-uzamcen" tabindex="-1">Účet byl uzamčen <a class="header-anchor" href="#ucet-byl-uzamcen" aria-label="Permalink to &quot;Účet byl uzamčen&quot;">​</a></h2><figure class="shot" style="--w:240px;"><img src="'+t+'" alt="Hláška Účet byl uzamčen" loading="lazy"></figure><p>Po pěti chybných pokusech za sebou se účet na 5 minut zamkne. Počkejte a zkuste to znovu, nebo si heslo obnovte přes <strong>Zapomněl jsem heslo</strong>.</p><h2 id="nelze-obnovit-heslo-u-propojeneho-uctu" tabindex="-1">Nelze obnovit heslo u propojeného účtu <a class="header-anchor" href="#nelze-obnovit-heslo-u-propojeneho-uctu" aria-label="Permalink to &quot;Nelze obnovit heslo u propojeného účtu&quot;">​</a></h2><figure class="shot" style="--w:240px;"><img src="'+o+'" alt="Hláška Nelze obnovit heslo u propojeného účtu" loading="lazy"></figure><p>Objeví se po kliknutí na <strong>Zapomněl jsem heslo</strong>. Váš účet je propojený s Microsoft účtem, takže heslo v Buildary nemá. Přihlaste se tlačítkem <strong>Přihlásit se pomocí Microsoft účtu</strong>.</p><h2 id="uzivatelske-jmeno-je-uz-zabrano" tabindex="-1">Uživatelské jméno je už zabráno <a class="header-anchor" href="#uzivatelske-jmeno-je-uz-zabrano" aria-label="Permalink to &quot;Uživatelské jméno je už zabráno&quot;">​</a></h2><figure class="shot" style="--w:240px;"><img src="'+s+'" alt="Hláška Uživatelské jméno je už zabráno" loading="lazy"></figure><p>Objeví se po odeslání registrace: účet s tímto e-mailem už existuje. Nezakládejte nový – <a href="/buildary-help-preview/firstofall/access">přihlaste se</a>. Pokud heslo nevíte, použijte <strong>Zapomněl jsem heslo</strong>.</p><h2 id="ucet-byl-jiz-aktivovan" tabindex="-1">Účet byl již aktivován <a class="header-anchor" href="#ucet-byl-jiz-aktivovan" aria-label="Permalink to &quot;Účet byl již aktivován&quot;">​</a></h2><figure class="shot" style="--w:240px;"><img src="'+l+'" alt="Hláška Účet byl již aktivován" loading="lazy"></figure><p>Aktivační kód jste použili podruhé. Nic dalšího dělat nemusíte, stačí se <a href="/buildary-help-preview/firstofall/access">přihlásit</a>.</p><h2 id="iat-is-in-the-future-exp-is-in-the-past" tabindex="-1">iat is in the future / exp is in the past <a class="header-anchor" href="#iat-is-in-the-future-exp-is-in-the-past" aria-label="Permalink to &quot;iat is in the future / exp is in the past&quot;">​</a></h2><div class="shots"><figure class="shot" style="--w:240px;"><img src="'+i+'" alt="Hláška iat is in the future" loading="lazy"></figure><figure class="shot" style="--w:240px;"><img src="'+n+'" alt="Hláška exp is in the past" loading="lazy"></figure></div><p>Hodiny ve vašem počítači nebo telefonu neodpovídají skutečnému času. V nastavení zařízení opravte čas, datum a časové pásmo (nejlépe zapněte automatické nastavení času) a přihlaste se znovu.</p>',20)])])}const z=r(m,[["render",c]]);export{y as __pageData,z as default};
